    fn rejects_unknown_action_classes_and_invalid_values() {
        assert!(parse(&VALID.replace("payment.read", "payments.delete")).is_err());
        assert!(parse(&VALID.replace("host = \"acme.com\"", "host = \"https://acme.com\"")).is_err());
        assert!(parse(&VALID.replace("action_class = \"payment.read\"", "path = \"relative\"\naction_class = \"payment.read\"")).is_err());
