//! Action classifier: maps `(method, host, path)` to an action class.
//!
//! Mapping configuration is compiled once. Requests are accepted only when
//! their method, authority, and path have an unambiguous ASCII interpretation.

mod config;
mod matcher;
mod normalize;

use std::fmt;

use config::parse;
use matcher::{CompileError, CompiledRule, find_conflict};

/// Action classes a rule may name. A rule naming anything else is invalid.
pub const ACTION_CLASSES: &[&str] = &[
    "payment.read",
    "payment.create",
    "payment.refund",
    "repo.read",
    "repo.write",
    "communication.external.send",
    "llm.inference",
];

/// Why a set of mapping files was rejected. Set and rule indexes are 0-based
/// positions in the `sets` slice and the set's `rules` array.
#[derive(Debug, thiserror::Error)]
pub enum LoadError {
    /// One mapping set is invalid on its own. `name` is absent when the set
    /// could not be parsed far enough to read it.
    #[error("mapping set {set}{}: {error}", display_name(.name))]
    InvalidSet {
        set: usize,
        name: Option<String>,
        #[source]
        error: SetError,
    },
    /// Two rules, possibly from different sets, can match the same request
    /// with equal specificity but name different action classes.
    #[error("{first} and {second} overlap with equal specificity but different action classes")]
    ConflictingRules {
        first: RuleLocation,
        second: RuleLocation,
    },
}

/// The reason a single mapping set is invalid.
#[derive(Debug, thiserror::Error)]
pub enum SetError {
    #[error("invalid TOML: {0}")]
    Toml(#[from] toml::de::Error),
    #[error("unsupported format version {0}; expected 1")]
    UnsupportedFormatVersion(u32),
    #[error("{0} must not be empty or malformed")]
    InvalidField(&'static str),
    #[error("rule {rule} has an invalid {field}")]
    InvalidRule { rule: usize, field: &'static str },
    #[error("rule {rule} names unsupported action class {action_class:?}")]
    UnknownActionClass { rule: usize, action_class: String },
}

/// Where a rule came from, for conflict diagnostics.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RuleLocation {
    pub set: usize,
    pub name: String,
    pub rule: usize,
}

impl fmt::Display for RuleLocation {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "mapping set {} {:?} rule {}",
            self.set, self.name, self.rule
        )
    }
}

fn display_name(name: &Option<String>) -> String {
    name.as_ref()
        .map(|name| format!(" {name:?}"))
        .unwrap_or_default()
}

/// An immutable, precompiled collection of mapping rules. Its contents are
/// owned strings and therefore it is `Send + Sync` without special handling.
pub struct Classifier {
    rules: Vec<CompiledRule>,
}

/// Parse, validate, compile, and combine mapping sets. Configuration conflicts
/// are rejected here, so mapping-file ordering never affects classification.
pub async fn load(sets: &[&str]) -> Result<Classifier, LoadError> {
    let mut rules = Vec::new();
    let mut locations = Vec::new();
    for (set_index, input) in sets.iter().enumerate() {
        let set = parse(input).map_err(|(name, error)| LoadError::InvalidSet {
            set: set_index,
            name,
            error,
        })?;
        for (rule_index, rule) in set.rules.into_iter().enumerate() {
            // Validation already ran these checks, so this mapping only
            // guards against the two modules drifting apart.
            let compiled = CompiledRule::new(
                rule.method.as_deref(),
                &set.host,
                rule.subdomain.as_deref(),
                rule.path.as_deref(),
                rule.action_class,
            )
            .map_err(|error| LoadError::InvalidSet {
                set: set_index,
                name: Some(set.name.clone()),
                error: SetError::InvalidRule {
                    rule: rule_index,
                    field: match error {
                        CompileError::Host => "subdomain",
                        CompileError::Method => "method",
                        CompileError::Path => "path",
                    },
                },
            })?;
            rules.push(compiled);
            locations.push(RuleLocation {
                set: set_index,
                name: set.name.clone(),
                rule: rule_index,
            });
        }
    }
    if let Some((first, second)) = find_conflict(&rules) {
        return Err(LoadError::ConflictingRules {
            first: locations[first].clone(),
            second: locations[second].clone(),
        });
    }
    Ok(Classifier { rules })
}

impl Classifier {
    /// Classifies a request. Malformed input is deliberately unclassified
    /// rather than coerced into a potentially broader rule.
    pub async fn classify(&self, method: &str, host: &str, path: &str) -> Option<&str> {
        let method = normalize::method(method)?;
        let host = normalize::host(host)?;
        let path = normalize::request_path(path)?;
        let class = self.best_match(&method, &host, &path);

        // Many servers route `/x/` and `/x` to the same handler. If the two
        // spellings classify differently we cannot know which action runs, so
        // the request is left unclassified (and therefore denied).
        if let Some(stripped) = path.strip_suffix('/').filter(|rest| !rest.is_empty()) {
            let alternative = self.best_match(&method, &host, stripped);
            if alternative.is_some() && alternative != class {
                return None;
            }
        }
        class
    }

    fn best_match(&self, method: &str, host: &str, path: &str) -> Option<&str> {
        self.rules
            .iter()
            .filter(|rule| rule.matches(method, host, path))
            .max_by(|left, right| left.compare_specificity(right))
            .map(|rule| rule.action_class.as_str())
    }
}
//! Compiled-rule matching, lexicographic specificity, and load-time conflicts.

use std::cmp::Ordering;

use crate::normalize;

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum HostPattern {
    Bare(String),
    Exact(String),
    AnySubdomain(String),
}

#[derive(Debug, Clone)]
pub(crate) struct CompiledRule {
    pub(crate) method: Option<String>,
    pub(crate) host: HostPattern,
    pub(crate) path: Option<String>,
    pub(crate) action_class: String,
    specificity: Specificity,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Specificity {
    host: u8,
    path_kind: u8,
    literal_count: usize,
    inverted_wildcard_count: usize,
    literal_prefix: usize,
    method: u8,
}

impl Ord for Specificity {
    fn cmp(&self, other: &Self) -> Ordering {
        (
            self.host,
            self.path_kind,
            self.literal_count,
            self.inverted_wildcard_count,
            self.literal_prefix,
            self.method,
        )
            .cmp(&(
                other.host,
                other.path_kind,
                other.literal_count,
                other.inverted_wildcard_count,
                other.literal_prefix,
                other.method,
            ))
    }
}

impl PartialOrd for Specificity {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

#[derive(Debug)]
pub(crate) enum CompileError {
    Host,
    Method,
    Path,
}

impl CompiledRule {
    pub(crate) fn new(
        method: Option<&str>,
        base_host: &str,
        subdomain: Option<&str>,
        path: Option<&str>,
        action_class: String,
    ) -> Result<Self, CompileError> {
        let base_host = normalize::host(base_host).ok_or(CompileError::Host)?;
        let host = match subdomain {
            None => HostPattern::Bare(base_host),
            Some("*") => HostPattern::AnySubdomain(base_host),
            Some(value) => {
                let value = normalize::host(value).ok_or(CompileError::Host)?;
                HostPattern::Exact(format!("{value}.{base_host}"))
            }
        };
        let method = match method {
            Some(value) => Some(normalize::method(value).ok_or(CompileError::Method)?),
            None => None,
        };
        let path = match path {
            Some(value) => Some(normalize::pattern_path(value).ok_or(CompileError::Path)?),
            None => None,
        };
        let specificity = specificity(&host, method.is_some(), path.as_deref());
        Ok(Self {
            method,
            host,
            path,
            action_class,
            specificity,
        })
    }

    pub(crate) fn matches(&self, method: &str, host: &str, path: &str) -> bool {
        self.method
            .as_deref()
            .is_none_or(|expected| expected == method)
            && host_matches(&self.host, host)
            && self
                .path
                .as_deref()
                .is_none_or(|pattern| glob_matches(pattern, path))
    }

    pub(crate) fn compare_specificity(&self, other: &Self) -> Ordering {
        self.specificity.cmp(&other.specificity)
    }
}

pub(crate) fn find_conflict(rules: &[CompiledRule]) -> Option<(usize, usize)> {
    for (right_index, right) in rules.iter().enumerate() {
        for (left_index, left) in rules[..right_index].iter().enumerate() {
            if left.action_class != right.action_class
                && left.specificity == right.specificity
                && methods_overlap(left.method.as_deref(), right.method.as_deref())
                && hosts_overlap(&left.host, &right.host)
                && paths_overlap(left.path.as_deref(), right.path.as_deref())
            {
                return Some((left_index, right_index));
            }
        }
    }
    None
}

fn specificity(host: &HostPattern, has_method: bool, path: Option<&str>) -> Specificity {
    let host = u8::from(!matches!(host, HostPattern::AnySubdomain(_)));
    let (path_kind, literal_count, wildcard_count, literal_prefix) = match path {
        None => (0, 0, 0, 0),
        Some(value) if !value.contains('*') => (2, value.len(), 0, value.len()),
        Some(value) => (
            1,
            value.bytes().filter(|byte| *byte != b'*').count(),
            value.bytes().filter(|byte| *byte == b'*').count(),
            value.find('*').unwrap_or(0),
        ),
    };
    Specificity {
        host,
        path_kind,
        literal_count,
        inverted_wildcard_count: usize::MAX - wildcard_count,
        literal_prefix,
        method: u8::from(has_method),
    }
}

fn host_matches(pattern: &HostPattern, host: &str) -> bool {
    match pattern {
        HostPattern::Bare(expected) | HostPattern::Exact(expected) => expected == host,
        HostPattern::AnySubdomain(base) => host
            .strip_suffix(base)
            .is_some_and(|prefix| prefix.ends_with('.') && prefix.len() > 1),
    }
}

fn methods_overlap(left: Option<&str>, right: Option<&str>) -> bool {
    left.is_none() || right.is_none() || left == right
}

fn hosts_overlap(left: &HostPattern, right: &HostPattern) -> bool {
    match (left, right) {
        (HostPattern::Bare(a), HostPattern::Bare(b))
        | (HostPattern::Bare(a), HostPattern::Exact(b))
        | (HostPattern::Exact(a), HostPattern::Bare(b))
        | (HostPattern::Exact(a), HostPattern::Exact(b)) => a == b,
        // These pairs cannot have equal host specificity, but retain correct
        // overlap semantics for callers that want them.
        (HostPattern::AnySubdomain(base), HostPattern::Bare(host))
        | (HostPattern::Bare(host), HostPattern::AnySubdomain(base))
        | (HostPattern::AnySubdomain(base), HostPattern::Exact(host))
        | (HostPattern::Exact(host), HostPattern::AnySubdomain(base)) => {
            host_matches(&HostPattern::AnySubdomain(base.clone()), host)
        }
        (HostPattern::AnySubdomain(a), HostPattern::AnySubdomain(b)) => {
            a == b || a.ends_with(&format!(".{b}")) || b.ends_with(&format!(".{a}"))
        }
    }
}

fn paths_overlap(left: Option<&str>, right: Option<&str>) -> bool {
    match (left, right) {
        (None, _) | (_, None) => true,
        (Some(left), Some(right)) => globs_overlap(left, right),
    }
}

pub(crate) fn glob_matches(pattern: &str, value: &str) -> bool {
    let pattern = pattern.as_bytes();
    let value = value.as_bytes();
    let (mut p, mut v, mut star, mut retry) = (0, 0, None, 0);
    while v < value.len() {
        while p < pattern.len() && pattern[p] == b'*' {
            star = Some(p);
            p += 1;
            retry = v;
        }
        if p < pattern.len() && pattern[p] == value[v] {
            p += 1;
            v += 1;
        } else if let Some(star_index) = star {
            p = star_index + 1;
            retry += 1;
            v = retry;
        } else {
            return false;
        }
    }
    while p < pattern.len() && pattern[p] == b'*' {
        p += 1;
    }
    p == pattern.len()
}

/// Product traversal of two `*` glob NFAs. The sentinel represents any byte
/// not currently present as a literal and keeps the alphabet finite.
fn globs_overlap(left: &str, right: &str) -> bool {
    let (left, right) = (left.as_bytes(), right.as_bytes());
    let mut seen = vec![vec![false; right.len() + 1]; left.len() + 1];
    let mut queue = std::collections::VecDeque::from([(0usize, 0usize)]);
    while let Some((i, j)) = queue.pop_front() {
        if seen[i][j] {
            continue;
        }
        seen[i][j] = true;
        if i == left.len() && j == right.len() {
            return true;
        }
        if left.get(i) == Some(&b'*') {
            queue.push_back((i + 1, j));
        }
        if right.get(j) == Some(&b'*') {
            queue.push_back((i, j + 1));
        }
        let mut alphabet = vec![0];
        if let Some(&byte) = left.get(i).filter(|&&byte| byte != b'*') {
            alphabet.push(byte);
        }
        if let Some(&byte) = right.get(j).filter(|&&byte| byte != b'*') {
            alphabet.push(byte);
        }
        for byte in alphabet {
            let next_left = transition(left, i, byte);
            let next_right = transition(right, j, byte);
            if let (Some(next_left), Some(next_right)) = (next_left, next_right) {
                queue.push_back((next_left, next_right));
            }
        }
    }
    false
}

fn transition(pattern: &[u8], index: usize, byte: u8) -> Option<usize> {
    match pattern.get(index) {
        Some(b'*') => Some(index),
        Some(&literal) if literal == byte => Some(index + 1),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::{CompiledRule, find_conflict, glob_matches};

    fn rule(
        subdomain: Option<&str>,
        method: Option<&str>,
        path: Option<&str>,
        action: &str,
    ) -> CompiledRule {
        CompiledRule::new(method, "acme.com", subdomain, path, action.into()).unwrap()
    }

    #[test]
    fn wildcard_hosts_respect_boundaries_and_nested_subdomains() {
        let rule = rule(Some("*"), None, None, "payment.read");
        assert!(rule.matches("GET", "a.b.acme.com", "/"));
        assert!(!rule.matches("GET", "acme.com", "/"));
        assert!(!rule.matches("GET", "evilacme.com", "/"));
    }

    #[test]
    fn globs_match_zero_or_more_characters() {
        assert!(glob_matches("/v1/refunds/*", "/v1/refunds/"));
        assert!(glob_matches("/v1/*/x/*", "/v1/a/b/x/c"));
        assert!(!glob_matches("/v1/refunds/*", "/v1/refunds"));
        assert!(glob_matches("/**/**/**", "/a/b/c/d"));
    }

    #[test]
    fn specificity_is_lexicographic() {
        let exact_host = rule(Some("api"), None, Some("/v1/*"), "payment.read");
        let wildcard_host = rule(
            Some("*"),
            Some("GET"),
            Some("/v1/payments"),
            "payment.create",
        );
        assert!(exact_host.compare_specificity(&wildcard_host).is_gt());
        let exact_path = rule(Some("api"), None, Some("/v1/payments"), "payment.read");
        assert!(exact_path.compare_specificity(&exact_host).is_gt());
    }

    #[test]
    fn detects_equal_specificity_overlaps_only() {
        let conflicting = vec![
            rule(Some("api"), None, Some("/v1/*a*bc"), "payment.read"),
            rule(Some("api"), None, Some("/v1/*ab*c"), "payment.refund"),
        ];
        assert_eq!(find_conflict(&conflicting), Some((0, 1)));
        let ordered = vec![
            rule(Some("api"), None, Some("/v1/*"), "payment.read"),
            rule(Some("api"), None, Some("/v1/payments"), "payment.refund"),
        ];
        assert_eq!(find_conflict(&ordered), None);
    }

    #[test]
    fn explicit_methods_win_only_after_host_and_path_ties() {
        let any_method = rule(Some("api"), None, Some("/v1/*"), "payment.read");
        let get = rule(Some("api"), Some("GET"), Some("/v1/*"), "payment.create");
        assert!(get.compare_specificity(&any_method).is_gt());
        assert!(get.matches("GET", "api.acme.com", "/v1/x"));
        assert!(!get.matches("get", "api.acme.com", "/v1/x"));
        assert!(!get.matches("POST", "api.acme.com", "/v1/x"));
        let lower = rule(Some("api"), Some("get"), Some("/v1/*"), "payment.create");
        assert_eq!(lower.method.as_deref(), Some("get"));
    }
}
//! Canonicalization for the three request components accepted by the classifier.
//!
//! This module deliberately accepts only the unambiguous ASCII subset of HTTP
//! authority and path syntax. In particular, IP literals, userinfo, encoded
//! separators, malformed percent escapes, and non-ASCII text are rejected.

/// Returns a lowercase DNS hostname without one optional trailing dot or port.
pub(crate) fn host(input: &str) -> Option<String> {
    if input.is_empty() || !input.is_ascii() || input.contains('@') {
        return None;
    }

    let (name, port) = match input.rsplit_once(':') {
        Some((name, port)) => (name, Some(port)),
        None => (input, None),
    };
    // Parsing also rejects values outside the TCP/UDP port range.
    if let Some(port) = port
        && (!port.bytes().all(|byte| byte.is_ascii_digit()) || port.parse::<u16>().is_err())
    {
        return None;
    }

    let name = name.strip_suffix('.').unwrap_or(name);
    if !is_dns_name(name) || name.parse::<std::net::Ipv4Addr>().is_ok() {
        return None;
    }
    Some(name.to_ascii_lowercase())
}

/// Validates an HTTP token without changing its case. HTTP method tokens are
/// case-sensitive, so `GET` and `get` are distinct matcher values.
pub(crate) fn method(input: &str) -> Option<String> {
    (!input.is_empty() && input.bytes().all(is_http_token)).then(|| input.into())
}

/// Normalizes a request path. Empty input represents the origin-form `/`.
pub(crate) fn request_path(input: &str) -> Option<String> {
    let end = input.find(['?', '#']).unwrap_or(input.len());
    let path = &input[..end];
    if path.is_empty() {
        return Some("/".into());
    }
    normalize_path(path, false)
}

/// Normalizes a configuration path pattern while retaining literal `*`
/// wildcards. Query strings and fragments never reach the matcher, so a
/// pattern containing one is a configuration mistake.
pub(crate) fn pattern_path(input: &str) -> Option<String> {
    if input.contains(['?', '#']) {
        return None;
    }
    normalize_path(input, true)
}

/// Canonical form shared by requests and patterns: unreserved percent escapes
/// decoded, other escapes upper-cased, and dot segments removed. Empty path
/// segments and trailing slashes are preserved; backslashes and encoded
/// separators are rejected because servers disagree on what they mean.
fn normalize_path(input: &str, pattern: bool) -> Option<String> {
    if !input.starts_with('/') {
        return None;
    }
    let decoded = decode_unreserved(input)?;

    // A dot segment next to a wildcard cannot be canonicalized …695 tokens truncated…
            remaining.replace_range(..4, "/");
            pop_last_segment(&mut output);
        } else if remaining == "." || remaining == ".." {
            remaining.clear();
        } else {
            let end = if let Some(stripped) = remaining.strip_prefix('/') {
                stripped
                    .find('/')
                    .map_or(remaining.len(), |index| index + 1)
            } else {
                remaining.find('/').unwrap_or(remaining.len())
            };
            output.push_str(&remaining[..end]);
            remaining.drain(..end);
        }
    }
    output
}

fn pop_last_segment(output: &mut String) {
    if let Some(index) = output.rfind('/') {
        output.truncate(index);
    } else {
        output.clear();
    }
}

fn is_dns_name(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 253
        && value.split('.').all(|label| {
            !label.is_empty()
                && label.len() <= 63
                && !label.starts_with('-')
                && !label.ends_with('-')
                && label
                    .bytes()
                    .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
        })
}

fn is_http_token(byte: u8) -> bool {
    byte.is_ascii_alphanumeric()
        || matches!(
            byte,
            b'!' | b'#'
                | b'$'
                | b'%'
                | b'&'
                | b'\''
                | b'*'
                | b'+'
                | b'-'
                | b'.'
                | b'^'
                | b'_'
                | b'`'
                | b'|'
                | b'~'
        )
}

#[cfg(test)]
mod tests {
    use super::{host, method, pattern_path, request_path};

    #[test]
    fn normalizes_hosts_and_rejects_ambiguous_authorities() {
        assert_eq!(host("API.Acme.COM.:443"), Some("api.acme.com".into()));
        for value in [
            "",
            "acme.com:",
            "acme.com:99999",
            "u@acme.com",
            "192.0.2.1",
            "[::1]",
            "acme..com",
            "é.com",
            "acme.com..",
        ] {
            assert_eq!(host(value), None, "{value}");
        }
    }

    #[test]
    fn methods_are_case_sensitive_tokens() {
        assert_eq!(method("GET"), Some("GET".into()));
        assert_eq!(method("delete"), Some("delete".into()));
        assert_eq!(method("Patch"), Some("Patch".into()));
        for value in ["", "GET ", "GET\n", "é"] {
            assert_eq!(method(value), None, "{value:?}");
        }
    }

    #[test]
    fn paths_strip_query_and_normalize_dot_segments() {
        assert_eq!(request_path(""), Some("/".into()));
        assert_eq!(request_path("/v1/../admin?q=1#x"), Some("/admin".into()));
        assert_eq!(request_path("/v1/%2e%2e/admin"), Some("/admin".into()));
        assert_eq!(request_path("/a/b/.."), Some("/a/".into()));
        assert_eq!(request_path("/a/./b/."), Some("/a/b/".into()));
        assert_eq!(request_path("/../../x"), Some("/x".into()));
        assert_eq!(request_path("/v1/payments/"), Some("/v1/payments/".into()));
        assert_eq!(request_path("/v1//payments"), Some("/v1//payments".into()));
        assert_eq!(
            request_path("//v1/payments/"),
            Some("//v1/payments/".into())
        );
        for value in [
            "relative", "/x%ZZ", "/x%2f", "/x%5C", "/x\\y", "/é", "/a b", "/a\0",
        ] {
            assert_eq!(request_path(value), None, "{value:?}");
        }
    }

    #[test]
    fn paths_decode_unreserved_escapes_only() {
        assert_eq!(request_path("/v1/%72efunds"), Some("/v1/refunds".into()));
        assert_eq!(request_path("/%7Euser/%5f"), Some("/~user/_".into()));
        assert_eq!(request_path("/a%3a%2A"), Some("/a%3A%2A".into()));
        // No double decoding: `%252e` is a literal `%2e`, not a dot segment.
        assert_eq!(
            request_path("/a/%252e%252e/b"),
            Some("/a/%252e%252e/b".into())
        );
    }

    #[test]
    fn patterns_retain_wildcards_but_reject_ambiguous_dot_patterns() {
        assert_eq!(
            pattern_path("/v1/*/refunds/**"),
            Some("/v1/*/refunds/**".into())
        );
        assert_eq!(
            pattern_path("/v1/%72efunds/*"),
            Some("/v1/refunds/*".into())
        );
        assert_eq!(pattern_path("/v1/*/../admin"), None);
        assert_eq!(pattern_path("/v1/*?debug=true"), None);
        assert_eq!(pattern_path("/v1//x"), Some("/v1//x".into()));
    }

    #[test]
    fn long_and_arbitrary_utf8_request_inputs_never_panic() {
        assert!(request_path(&format!("/{}", "a".repeat(32 * 1024))).is_some());
        for value in ["\0", "\u{10ffff}", "/\u{10ffff}", "/%"] {
            assert_eq!(request_path(value), None, "{value:?}");
        }
    }
}
//! Parsing and validation for mapping-set TOML documents.

use serde::Deserialize;

use crate::{ACTION_CLASSES, SetError, normalize};

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct MappingSet {
    pub(crate) format_version: u32,
    pub(crate) name: String,
    pub(crate) description: Option<String>,
    pub(crate) host: String,
    pub(crate) rules: Vec<Rule>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct Rule {
    pub(crate) method: Option<String>,
    pub(crate) subdomain: Option<String>,
    pub(crate) path: Option<String>,
    pub(crate) action_class: String,
}

/// Converts one TOML document to a checked mapping set. Errors carry the
/// set's declared name when the document parsed far enough to have one.
pub(crate) fn parse(input: &str) -> Result<MappingSet, (Option<String>, SetError)> {
    let set: MappingSet = toml::from_str(input).map_err(|error| (None, SetError::Toml(error)))?;
    match validate(&set) {
        Ok(()) => Ok(set),
        Err(error) => Err((Some(set.name), error)),
    }
}

fn validate(set: &MappingSet) -> Result<(), SetError> {
    if set.format_version != 1 {
        return Err(SetError::UnsupportedFormatVersion(set.format_version));
    }
    required_text("name", &set.name)?;
    if set
        .description
        .as_deref()
        .is_some_and(|description| description.chars().any(char::is_control))
    {
        return Err(SetError::InvalidField("description"));
    }
    validate_host(&set.host)?;
    if set.rules.is_empty() {
        return Err(SetError::InvalidField("rules"));
    }

    for (index, rule) in set.rules.iter().enumerate() {
        if !ACTION_CLASSES.contains(&rule.action_class.as_str()) {
            return Err(SetError::UnknownActionClass {
                rule: index,
                action_class: rule.action_class.clone(),
            });
        }
        if let Some(method) = &rule.method
            && normalize::method(method).is_none()
        {
            return Err(SetError::InvalidRule {
                rule: index,
                field: "method",
            });
        }
        if let Some(subdomain) = &rule.subdomain
            && subdomain != "*"
            && (!is_dns_label(subdomain) || normalize::host(subdomain).is_none())
        {
            return Err(SetError::InvalidRule {
                rule: index,
                field: "subdomain",
            });
        }
        if let Some(path) = &rule.path
            && normalize::pattern_path(path).is_none()
        {
            return Err(SetError::InvalidRule {
                rule: index,
                field: "path",
            });
        }
    }
    Ok(())
}

fn required_text(field: &'static str, value: &str) -> Result<(), SetError> {
    if value.trim().is_empty() || value.chars().any(char::is_control) {
        Err(SetError::InvalidField(field))
    } else {
        Ok(())
    }
}

fn validate_host(host: &str) -> Result<(), SetError> {
    // Mapping hosts name an origin, not an HTTP authority. Ports and trailing
    // dots are accepted for request authorities but create duplicate mapping
    // identities, so reject them here.
    if !host.contains(':')
        && !host.ends_with('.')
        && normalize::host(host).is_some()
        && is_dns_name(host)
    {
        Ok(())
    } else {
        Err(SetError::InvalidField("host"))
    }
}

fn is_dns_name(value: &str) -> bool {
    !value.is_empty() && value.len() <= 253 && value.split('.').all(is_dns_label)
}

fn is_dns_label(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 63
        && !value.starts_with('-')
        && !value.ends_with('-')
        && value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
}

