    /// Classifies a request. Malformed input is deliberately unclassified
    /// rather than coerced into a potentially broader rule.
    pub async fn classify(&self, method: &str, host: &str, path: &str) -> Option<&str> {
        let method = normalize::method(method)?;
        let host = normalize::host(host)?;
        let path = normalize::request_path(path)?;
        let class = self.best_match(&method, &host, &path);

        // Many servers route `/x/` and `/x` to the same handler. If the two
        // spellings classify differently we cannot know which action runs, so
        // the request is left unclassified (and therefore denied).
        let alternate_path = match path.strip_suffix('/').filter(|rest| !rest.is_empty()) {
            Some(stripped) => stripped.to_owned(),
            None if path != "/" => format!("{path}/"),
            None => return class,
        };
        if let (Some(class), Some(alternative)) =
            (class, self.best_match(&method, &host, &alternate_path))
            && alternative != class
        {
            c.classify("POST", "api.acme.com", path).await,
            None,
            "{path}"
        );
    }
}

#[tokio::test]
async fn trailing_slash_that_changes_the_class_is_unclassified() {
    let c = load(&[ACME]).await.unwrap();
    // The alternative trailing-slash spelling falls through to `/v1/*`, so
    // neither form may be classified.
    assert_eq!(
        c.classify("POST", "api.acme.com", "/v1/payouts").await,
        None
    );
    assert_eq!(
        c.classify("POST", "api.acme.com", "/v1/payouts/").await,
        None
    );
    // No disagreement: both spellings are payment.read.
    assert_eq!(
        c.classify("GET", "api.acme.com", "/v1/balance").await,
        Some("payment.read")
    );
    assert_eq!(
        c.classify("GET", "api.acme.com", "/v1/balance/").await,
        Some("payment.read")
    );
}

#[tokio::test]
async fn dot_segments_resolve_before_matching() {
    let c = load(&[ACME]).await.unwrap();
    assert_eq!(
        c.classify("POST", "api.acme.com", "/v1/balance/../refunds/x")
            .await,
        Some("payment.refund")
    );
    assert_eq!(
        c.classify("POST", "api.acme.com", "/v1/balance/%2e%2e/refunds/x")
            .await,
        Some("payment.refund")
    );
#[tokio::test]
async fn most_specific_rule_wins() {
    let c = load(&[ACME]).await.unwrap();
    let cases = [
        // Exact subdomain beats wildcard subdomain even with a broader path.
        ("GET", "/v1/x", Some("payment.read")),
        // Explicit method beats omitted method once host and path tie.
        ("POST", "/v1/x", Some("payment.create")),
        // More literal characters beat a method on a broader pattern.
        ("POST", "/v1/refunds/r1", Some("payment.refund")),
        // The slash-appended form falls back to `/v1/*`, so both spellings
        // are conservatively unclassified.
        ("GET", "/v1/msg/send", None),
        // A path no exact-host rule covers falls back to the wildcard host.
        ("GET", "/v2/x", Some("repo.read")),
    ];
    for (method, path, expected) in cases {
        assert_eq!(
            c.classify(method, "api.acme.com", path).await,
            expected,
            "{method} {path}"
        );
    }
}

