//! Compiled-rule matching, lexicographic specificity, and load-time conflicts.

use std::cmp::Ordering;

use crate::{ACTION_CLASSES, normalize};

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum HostPattern {
    Bare(String),
    Exact(String),
    AnySubdomain(String),
}

#[derive(Debug, Clone)]
pub(crate) struct CompiledRule {
    pub(crate) method: Option<String>,
    pub(crate) host: HostPattern,
    pub(crate) path: Option<String>,
    pub(crate) action_class: &'static str,
    specificity: Specificity,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Specificity {
    host: u8,
    path_kind: u8,
    literal_count: usize,
    inverted_wildcard_count: usize,
    literal_prefix: usize,
    method: u8,
}

impl Ord for Specificity {
    fn cmp(&self, other: &Self) -> Ordering {
        (
            self.host,
            self.path_kind,
            self.literal_count,
            self.inverted_wildcard_count,
            self.literal_prefix,
            self.method,
        )
            .cmp(&(
                other.host,
                other.path_kind,
                other.literal_count,
                other.inverted_wildcard_count,
                other.literal_prefix,
                other.method,
            ))
    }
}

impl PartialOrd for Specificity {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

#[derive(Debug)]
pub(crate) enum CompileError {
    Host,
    Method,
    Path,
    ActionClass(String),
}

#[derive(Debug)]
pub(crate) enum ConflictCheckError {
    TooComplex { first: usize, second: usize },
}

impl CompiledRule {
    pub(crate) fn new(
        method: Option<&str>,
        base_host: &str,
        subdomain: Option<&str>,
        path: Option<&str>,
        action_class: String,
    ) -> Result<Self, CompileError> {
        let base_host = normalize::host(base_host).ok_or(CompileError::Host)?;
        let host = match subdomain {
            None => HostPattern::Bare(base_host),
            Some("*") => HostPattern::AnySubdomain(base_host),
            Some(value) => {
                let value = normalize::host(value).ok_or(CompileError::Host)?;
                HostPattern::Exact(format!("{value}.{base_host}"))
            }
        };
        let method = match method {
            Some(value) => Some(normalize::method(value).ok_or(CompileError::Method)?),
            None => None,
        };
        let path = match path {
            Some(value) => Some(normalize::pattern_path(value).ok_or(CompileError::Path)?),
            None => None,
        };
        let action_class = ACTION_CLASSES
            .iter()
            .copied()
            .find(|known| *known == action_class)
            .ok_or(CompileError::ActionClass(action_class))?;
        let specificity = specificity(&host, method.is_some(), path.as_deref());
        Ok(Self {
            method,
            host,
            path,
            action_class,
            specificity,
        })
    }

    pub(crate) fn matches(&self, method: &str, host: &str, path: &str) -> bool {
        self.method
            .as_deref()
            .is_none_or(|expected| expected == method)
            && host_matches(&self.host, host)
            && self
                .path
                .as_deref()
                .is_none_or(|pattern| glob_matches(pattern, path))
    }

    pub(crate) fn compare_specificity(&self, other: &Self) -> Ordering {
        self.specificity.cmp(&other.specificity)
    }
}

pub(crate) fn find_conflict(
    rules: &[CompiledRule],
) -> Result<Option<(usize, usize)>, ConflictCheckError> {
    let mut checked_pairs = 0;
    for (right_index, right) in rules.iter().enumerate() {
        for (left_index, left) in rules[..right_index].iter().enumerate() {
            checked_pairs += 1;
            if checked_pairs > MAX_CONFLICT_PAIR_CHECKS {
                return Err(ConflictCheckError::TooComplex {
                    first: left_index,
                    second: right_index,
                });
            }
            if left.action_class != right.action_class
                && left.specificity == right.specificity
                && methods_overlap(left.method.as_deref(), right.method.as_deref())
                && hosts_overlap(&left.host, &right.host)
            {
                match paths_overlap(left.path.as_deref(), right.path.as_deref()) {
                    Ok(true) => return Ok(Some((left_index, right_index))),
                    Ok(false) => {}
                    Err(()) => {
                        return Err(ConflictCheckError::TooComplex {
                            first: left_index,
                            second: right_index,
                        });
                    }
                }
            }
        }
    }
    Ok(None)
}

fn specificity(host: &HostPattern, has_method: bool, path: Option<&str>) -> Specificity {
    let host = u8::from(!matches!(host, HostPattern::AnySubdomain(_)));
    let (path_kind, literal_count, wildcard_count, literal_prefix) = match path {
        None => (0, 0, 0, 0),
        Some(value) if !value.contains('*') => (2, value.len(), 0, value.len()),
        Some(value) => (
            1,
            value.bytes().filter(|byte| *byte != b'*').count(),
            value.bytes().filter(|byte| *byte == b'*').count(),
            value.find('*').unwrap_or(0),
        ),
    };
    Specificity {
        host,
        path_kind,
        literal_count,
        inverted_wildcard_count: usize::MAX - wildcard_count,
        literal_prefix,
        method: u8::from(has_method),
    }
}

fn host_matches(pattern: &HostPattern, host: &str) -> bool {
    match pattern {
        HostPattern::Bare(expected) | HostPattern::Exact(expected) => expected == host,
        HostPattern::AnySubdomain(base) => host
            .strip_suffix(base)
            .is_some_and(|prefix| prefix.ends_with('.') && prefix.len() > 1),
    }
}

fn methods_overlap(left: Option<&str>, right: Option<&str>) -> bool {
    left.is_none() || right.is_none() || left == right
}

fn hosts_overlap(left: &HostPattern, right: &HostPattern) -> bool {
    match (left, right) {
        (HostPattern::Bare(a), HostPattern::Bare(b))
        | (HostPattern::Bare(a), HostPattern::Exact(b))
        | (HostPattern::Exact(a), HostPattern::Bare(b))
        | (HostPattern::Exact(a), HostPattern::Exact(b)) => a == b,
        // These pairs cannot have equal host specificity, but retain correct
        // overlap semantics for callers that want them.
        (HostPattern::AnySubdomain(base), HostPattern::Bare(host))
        | (HostPattern::Bare(host), HostPattern::AnySubdomain(base))
        | (HostPattern::AnySubdomain(base), HostPattern::Exact(host))
        | (HostPattern::Exact(host), HostPattern::AnySubdomain(base)) => {
            host_matches(&HostPattern::AnySubdomain(base.clone()), host)
        }
        (HostPattern::AnySubdomain(a), HostPattern::AnySubdomain(b)) => {
            a == b || a.ends_with(&format!(".{b}")) || b.ends_with(&format!(".{a}"))
        }
    }
}

fn paths_overlap(left: Option<&str>, right: Option<&str>) -> Result<bool, ()> {
    match (left, right) {
        (None, _) | (_, None) => Ok(true),
        (Some(left), Some(right)) => globs_overlap(left, right),
    }
}

pub(crate) fn glob_matches(pattern: &str, value: &str) -> bool {
    let pattern = pattern.as_bytes();
    let value = value.as_bytes();
    let (mut p, mut v, mut star, mut retry) = (0, 0, None, 0);
    while v < value.len() {
        while p < pattern.len() && pattern[p] == b'*' {
            star = Some(p);
            p += 1;
            retry = v;
        }
        if p < pattern.len() && pattern[p] == value[v] {
            p += 1;
            v += 1;
        } else if let Some(star_index) = star {
            p = star_index + 1;
            retry += 1;
            v = retry;
        } else {
            return false;
        }
    }
    while p < pattern.len() && pattern[p] == b'*' {
        p += 1;
    }
    p == pattern.len()
}

/// Product traversal of two `*` glob NFAs. The sentinel represents any byte
/// not currently present as a literal and keeps the alphabet finite.
const MAX_GLOB_OVERLAP_STATES: usize = 1_000_000;
const MAX_CONFLICT_PAIR_CHECKS: usize = 100_000;

fn globs_overlap(left: &str, right: &str) -> Result<bool, ()> {
    let (left, right) = (left.as_bytes(), right.as_bytes());
    let width = right.len().checked_add(1).ok_or(())?;
    let states = left
        .len()
        .checked_add(1)
        .and_then(|height| height.checked_mul(width))
        .filter(|states| *states <= MAX_GLOB_OVERLAP_STATES)
        .ok_or(())?;
    let mut seen = vec![false; states];
    let mut queue = std::collections::VecDeque::from([(0usize, 0usize)]);
    while let Some((i, j)) = queue.pop_front() {
        let state = i * width + j;
        if seen[state] {
            continue;
        }
        seen[state] = true;
        if i == left.len() && j == right.len() {
            return Ok(true);
        }
        if left.get(i) == Some(&b'*') {
            queue.push_back((i + 1, j));
        }
        if right.get(j) == Some(&b'*') {
            queue.push_back((i, j + 1));
        }
        let mut alphabet = vec![0];
        if let Some(&byte) = left.get(i).filter(|&&byte| byte != b'*') {
            alphabet.push(byte);
        }
        if let Some(&byte) = right.get(j).filter(|&&byte| byte != b'*') {
            alphabet.push(byte);
        }
        for byte in alphabet {
            let next_left = transition(left, i, byte);
            let next_right = transition(right, j, byte);
            if let (Some(next_left), Some(next_right)) = (next_left, next_right) {
                queue.push_back((next_left, next_right));
            }
        }
    }
    Ok(false)
}

//! Action classifier: maps `(method, host, path)` to an action class.
//!
//! Mapping configuration is compiled once. Requests are accepted only when
//! their method, authority, and path have an unambiguous ASCII interpretation.

mod config;
mod matcher;
mod normalize;

use std::fmt;

use config::parse;
use matcher::{CompileError, CompiledRule, ConflictCheckError, find_conflict};

/// Action classes a rule may name. A rule naming anything else is invalid.
pub const ACTION_CLASSES: &[&str] = &[
    "payment.read",
    "payment.create",
    "payment.refund",
    "repo.read",
    "repo.write",
    "communication.external.send",
    "llm.inference",
];

const MAX_TOTAL_RULES: usize = 10_000;

/// Why a set of mapping files was rejected. Set and rule indexes are 0-based
/// positions in the `sets` slice and the set's `rules` array.
#[derive(Debug, thiserror::Error)]
pub enum LoadError {
    /// One mapping set is invalid on its own. `name` is absent when the set
    /// could not be parsed far enough to read it.
    #[error("mapping set {set}{}: {error}", display_name(.name))]
    InvalidSet {
        set: usize,
        name: Option<String>,
        #[source]
        error: SetError,
    },
    /// Two rules, possibly from different sets, can match the same request
    /// with equal specificity but name different action classes.
    #[error("{first} and {second} overlap with equal specificity but different action classes")]
    ConflictingRules {
        first: RuleLocation,
        second: RuleLocation,
    },
    /// Two wildcard patterns require more overlap-analysis state than the
    /// loader safely permits. Rejecting prevents configuration-driven memory
    /// exhaustion without silently accepting an unresolved ambiguity.
    #[error("{first} and {second} require excessive conflict analysis")]
    ConflictAnalysisTooComplex {
        first: RuleLocation,
        second: RuleLocation,
    },
    #[error("mapping configuration contains more than {limit} rules")]
    TooManyRules { limit: usize },
}

/// The reason a single mapping set is invalid.
#[derive(Debug, thiserror::Error)]
pub enum SetError {
    #[error("invalid TOML: {0}")]
    Toml(#[from] toml::de::Error),
    #[error("unsupported format version {0}; expected 1")]
    UnsupportedFormatVersion(u32),
    #[error("{0} must not be empty or malformed")]
    InvalidField(&'static str),
    #[error("rule {rule} has an invalid {field}")]
    InvalidRule { rule: usize, field: &'static str },
    #[error("rule {rule} names unsupported action class {action_class:?}")]
    UnknownActionClass { rule: usize, action_class: String },
}

/// Where a rule came from, for conflict diagnostics.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RuleLocation {
    pub set: usize,
    pub name: String,
    pub rule: usize,
}

impl fmt::Display for RuleLocation {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "mapping set {} {:?} rule {}",
            self.set, self.name, self.rule
        )
    }
}

fn display_name(name: &Option<String>) -> String {
    name.as_ref()
        .map(|name| format!(" {name:?}"))
        .unwrap_or_default()
}

/// An immutable, precompiled collection of mapping rules. Its contents are
/// owned strings and therefore it is `Send + Sync` without special handling.
pub struct Classifier {
    rules: Vec<CompiledRule>,
}

/// Parse, validate, compile, and combine mapping sets. Configuration conflicts
/// are rejected here, so mapping-file ordering never affects classification.
pub async fn load(sets: &[&str]) -> Result<Classifier, LoadError> {
    let mut rules = Vec::new();
    let mut locations = Vec::new();
    for (set_index, input) in sets.iter().enumerate() {
        let set = parse(input).map_err(|(name, error)| LoadError::InvalidSet {
            set: set_index,
            name,
            error,
        })?;
        for (rule_index, rule) in set.rules.into_iter().enumerate() {
            if rules.len() == MAX_TOTAL_RULES {
                return Err(LoadError::TooManyRules {
                    limit: MAX_TOTAL_RULES,
                });
            }
            // Validation already ran these checks, so this mapping only
            // guards against the two modules drifting apart.
            let compiled = CompiledRule::new(
                rule.method.as_deref(),
                &set.host,
                rule.subdomain.as_deref(),
                rule.path.as_deref(),
                rule.action_class,
            )
            .map_err(|error| {
                let error = match error {
                    CompileError::Host => SetError::InvalidRule {
                        rule: rule_index,
                        field: "subdomain",
                    },
                    CompileError::Method => SetError::InvalidRule {
                        rule: rule_index,
                        field: "method",
                    },
                    CompileError::Path => SetError::InvalidRule {
                        rule: rule_index,
                        field: "path",
                    },
                    CompileError::ActionClass(action_class) => SetError::UnknownActionClass {
                        rule: rule_index,
                        action_class,
                    },
                };
                LoadError::InvalidSet {
                    set: set_index,
                    name: Some(set.name.clone()),
                    error,
                }
            })?;
            rules.push(compiled);
            locations.push(RuleLocation {
                set: set_index,
                name: set.name.clone(),
                rule: rule_index,
            });
        }
    }
    match find_conflict(&rules) {
        Ok(Some((first, second))) => {
            return Err(LoadError::ConflictingRules {
                first: locations[first].clone(),
                second: locations[second].clone(),
            });
        }
        Ok(None) => {}
        Err(ConflictCheckError::TooComplex { first, second }) => {
            return Err(LoadError::ConflictAnalysisTooComplex {
                first: locations[first].clone(),
                second: locations[second].clone(),
            });
        }
    }
    Ok(Classifier { rules })
}

impl Classifier {
    /// Classifies a request. Malformed input is deliberately unclassified
    /// rather than coerced into a potentially broader rule.
    pub async fn classify(&self, method: &str, host: &str, path: &str) -> Option<&str> {
        let method = normalize::method(method)?;
        let host = normalize::host(host)?;
        let path = normalize::request_path(path)?;
        let class = self.best_match(&method, &host, &path);

        // A server may strip a trailing slash and route to a more sensitive
        // handler. A request sent without one is classified as sent, so only
        // the trailing-slash spelling needs this conservative comparison.
        if let Some(stripped) = path.strip_suffix('/').filter(|rest| !rest.is_empty()) {
            let alternative = self.best_match(&method, &host, stripped);
            if alternative.is_some() && alternative != class {
                return None;
            }
        }
        class
    }

    fn best_match(&self, method: &str, host: &str, path: &str) -> Option<&str> {
        self.rules
            .iter()
            .filter(|rule| rule.matches(method, host, path))
            .max_by(|left, right| left.compare_specificity(right))
            .map(|rule| rule.action_class)
    }
}
